{"command": "create", "path": "/workspace/source/apps/customer-service/src/erasure-repository.ts", "file_text": "import type { PoolClient } from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  idempotency_key: string | null;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export class ErasureRepository {
  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByIdempotencyKey(merchantId: string, customerId: string, key: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 AND idempotency_key=$3`,
      [merchantId, customerId, key],
    );
    return result.rows[0];
  }

  async findIdempotencyKeyForOtherCustomer(merchantId: string, customerId: string, key: string): Promise<string | undefined> {
    const result = await pool.query<{ customer_id: string }>(
      `SELECT customer_id FROM customers.erasure_requests
       WHERE merchant_id=$1 AND customer_id<>$2 AND idempotency_key=$3`,
      [merchantId, customerId, key],
    );
    return result.rows[0]?.customer_id;
  }

  async create(client: PoolClient, merchantId: string, customerId: string, idempotencyKey: string | null): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id, customer_id, idempotency_key)
       VALUES($1, $2, $3) RETURNING *`,
      [merchantId, customerId, idempotencyKey],
    );
    return result.rows[0]!;
  }

  async markProcessing(client: PoolClient, id: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests SET status='processing', attempts=attempts+1, updated_at=now()
       WHERE id=$1`,
      [id],
    );
  }

  async markFailed(client: PoolClient, id: string, error: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests SET status='failed', last_error=$2, updated_at=now()
       WHERE id=$1`,
      [id, error],
    );
  }

  async markCompleted(client: PoolClient, id: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests SET status='completed', completed_at=now(), updated_at=now()
       WHERE id=$1`,
      [id],
    );
  }

  async claimNextPending(workerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, updated_at=now()
       WHERE id=(SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed','retry') AND attempts < 8
         ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING *`,
    );
    return result.rows[0] ?? undefined;
  }

  // ---- Data deletion helpers ----

  async anonymizeCustomer(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.customers SET email='deleted-'||id::text||'@payflow.internal',
       name='Deleted Customer', phone=NULL, status='deleted', updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteAddresses(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteContacts(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async wipePaymentMethods(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token='', billing_name=NULL, billing_address=NULL, status='deleted'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeSupportMessages(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.support_messages SET body='[deleted]'
       WHERE author_type='customer' AND author_id=$1`,
      [customerId],
    );
  }

  async anonymizePaymentIntents(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents SET customer_snapshot='{"deleted":true}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeRefunds(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.refunds SET customer_email=NULL
       WHERE merchant_id=$1 AND payment_intent_id IN
         (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
  }

  async anonymizeInvoices(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot='{"deleted":true}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async deleteNotificationPreferences(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeAnalyticsEvents(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events SET email=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeEmailDeliveries(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.email_deliveries SET destination='deleted-'||customer_id::text||'@payflow.internal'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeNotifications(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.notifications SET destination='deleted-'||customer_id::text||'@payflow.internal'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeDocumentManifests(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.document_manifests SET customer_id=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  async anonymizeProviderCustomers(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers SET email='deleted@payflow.internal', name='Deleted Customer', updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId],
    );
  }
}"}

{"command": "create", "path": "/workspace/source/apps/customer-service/src/erasure-service.ts", "file_text": "import { v4 as uuid } from 'uuid';
import type { PoolClient } from 'pg';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';
import { CustomerRepository } from './repository.js';

const STABLE_ERRORS: Record<string, string> = {
  CUSTOMER_NOT_FOUND: 'customer_not_found',
  CUSTOMER_ALREADY_DELETED: 'customer_already_deleted',
  ERASURE_FAILED: 'erasure_failed',
};

export class ErasureService {
  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly customerRepository = new CustomerRepository(),
  ) {}

  /** Returns {request, status} where status is 202 for new, 200 for existing, 409 for conflict. */
  async createOrGetRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string | null,
  ): Promise<{ request: ErasureRequestRow; status: number }> {
    // Check if customer exists
    const customer = await this.customerRepository.find(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer not found'), { statusCode: 404 });

    // Check for an existing erasure request
    const existing = await this.repository.findByCustomer(merchantId, customerId);
    if (existing) {
      return { request: existing, status: 200 };
    }

    // Idempotency key handling
    if (idempotencyKey) {
      const idempotent = await this.repository.findByIdempotencyKey(merchantId, customerId, idempotencyKey);
      if (idempotent) {
        return { request: idempotent, status: 200 };
      }
      // Check if this idempotency key is used for a different customer
      const otherCustomer = await this.repository.findIdempotencyKeyForOtherCustomer(merchantId, customerId, idempotencyKey);
      if (otherCustomer) {
        throw Object.assign(new Error('idempotency key reused with different customer'), { statusCode: 409 });
      }
    }

    const request = await transaction(async (client) => {
      const created = await this.repository.create(client, merchantId, customerId, idempotencyKey);
      const correlationId = uuid();
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId,
        payload: { erasureRequestId: created.id, customerId },
      });
      return created;
    });

    return { request, status: 202 };
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasureRequestRow> {
    const request = await this.repository.findById(merchantId, requestId);
    if (!request) throw Object.assign(new Error('erasure request not found'), { statusCode: 404 });
    return request;
  }

  /** Performs all cleanup steps for a single erasure request. Must be idempotent. */
  async processErasure(request: ErasureRequestRow, workerId: string): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId, id } = request;

    try {
      await transaction(async (client) => {
        await this.repository.markProcessing(client, id);
        await this.performCleanup(client, merchantId, customerId);
        await this.repository.markCompleted(client, id);
        await addOutboxEvent(client, {
          eventType: EVENT_TYPES.CUSTOMER_ERASURE_COMPLETED,
          aggregateType: 'customer',
          aggregateId: customerId,
          merchantId,
          correlationId: uuid(),
          payload: { erasureRequestId: id, customerId },
        });
      });
      logger.info({ erasureRequestId: id, customerId, merchantId }, 'erasure completed');
    } catch (error) {
      const message = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
      const stableCode = STABLE_ERRORS.ERASURE_FAILED;
      await transaction(async (client) => {
        await this.repository.markFailed(client, id, stableCode);
      });
      logger.error({ erasureRequestId: id, error: message }, 'erasure failed');
    }
  }

  private async performCleanup(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    // Verify customer still exists and belongs to merchant
    const customer = await this.customerRepository.find(merchantId, customerId);
    if (!customer) return; // Already gone, safe to continue

    await this.repository.wipePaymentMethods(client, merchantId, customerId);
    await this.repository.deleteAddresses(client, merchantId, customerId);
    await this.repository.deleteContacts(client, merchantId, customerId);
    await this.repository.anonymizeSupportMessages(client, merchantId, customerId);
    await this.repository.anonymizePaymentIntents(client, merchantId, customerId);
    await this.repository.anonymizeRefunds(client, merchantId, customerId);
    await this.repository.anonymizeInvoices(client, merchantId, customerId);
    await this.repository.deleteNotificationPreferences(client, merchantId, customerId);
    await this.repository.anonymizeAnalyticsEvents(client, merchantId, customerId);
    await this.repository.anonymizeEmailDeliveries(client, merchantId, customerId);
    await this.repository.anonymizeNotifications(client, merchantId, customerId);
    await this.repository.anonymizeDocumentManifests(client, merchantId, customerId);
    await this.repository.anonymizeProviderCustomers(client, merchantId, customerId);
    await this.repository.anonymizeCustomer(client, merchantId, customerId);
  }
}"}

