/** Background erasure worker that processes pending erasure requests. */
async function runErasureWorker(signal: AbortSignal): Promise<void> {
  const erasureRepository = new ErasureRepository();
  const erasureService = new ErasureService();
  const workerId = `customer-service-erasure-${randomUUID()}`;
  while (!signal.aborted) {
    const request = await erasureRepository.claimNextPending(workerId);
    if (request) {
